package android.text; public class SpannableStringBuilder implements Spannable { StringBuilder b=new StringBuilder(); public SpannableStringBuilder append(CharSequence s){b.append(s);return this;} public void setSpan(Object w,int x,int y,int f){} public int length(){return b.length();} public char charAt(int i){return b.charAt(i);} public CharSequence subSequence(int x,int y){return b.subSequence(x,y);} public String toString(){return b.toString();} }
